mapper.insert:
INSERT INTO J_직원_재직기간 (직원아이디, 재직순번, 입사일, 가중퍼센트, 직급반영여부)
VALUES (#{userId},
        (SELECT ISNULL(MAX(재직순번), 0) + 1 FROM J_직원_재직기간 WHERE 직원아이디 = #{userId}),
        #{hireDate,jdbcType=DATE},
        #{weightPercent,jdbcType=INTEGER},
        ISNULL(#{reflectPosition}, 0));

UPDATE J_직원 SET 현재재직상태 = N'재직', 수정일 = GETDATE() WHERE 아이디 = #{userId};

UPDATE J_직원_계정 SET 계정상태 = N'사용' WHERE 아이디 = #{userId} AND 계정상태 = N'정지';

INSERT INTO J_직원_발령이력 (아이디, 발령유형, 발령일, 사유, 등록일시)
VALUES (#{userId}, N'재입사', #{hireDate,jdbcType=DATE}, #{reason,jdbcType=NVARCHAR}, GETDATE());

mapper.update:
UPDATE J_직원 SET 현재재직상태 = N'퇴사', 수정일 = GETDATE() WHERE 아이디 = #{userId};

UPDATE J_직원_재직기간
SET 퇴사일 = ISNULL(#{resignDate,jdbcType=DATE}, CAST(GETDATE() AS date)),
    퇴사사유 = #{resignReason,jdbcType=NVARCHAR}
WHERE 직원아이디 = #{userId} AND 퇴사일 IS NULL;

INSERT INTO J_직원_발령이력 (아이디, 발령유형, 발령일, 사유, 등록일시)
VALUES (#{userId}, N'퇴사', ISNULL(#{resignDate,jdbcType=DATE}, CAST(GETDATE() AS date)),
        #{resignReason,jdbcType=NVARCHAR}, GETDATE());
